for seq, expected in [([5, 8, 3, 7, 2, 6, 9], 9), ([4, 1, 3, 6, 7, 5, 8], 8), ([], None)]:
    b = BST()
    for i in seq: b.insert(i)
    assert b.max() == expected

for seq in [[0], [1, 2], [1, 2, 3], [1, 2, 3, 5], [1, 2, 3, 5, 8], list(range(20))]:
    ll = LinkedList()
    for x in seq: ll.insert(x)
    assert ll.middle() == seq[len(seq) // 2]
